(()=>{'use strict';
const paths={home:'<path d="M3 10 12 3l9 7v10h-6v-6H9v6H3z"/>',plan:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',methods:'<path d="M4 19V9m0 10h16M8 15l4-4 3 2 5-7"/><path d="M17 6h3v3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>',chart:'<circle cx="12" cy="12" r="8"/><path d="M12 4v8l6 5"/>',alerts:'<path d="M18 8a6 6 0 0 0-12 0c0 7-2 7-2 9h16c0-2-2-2-2-9M10 21h4"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
const entries=[['home','Inicio','Home'],['plan','Plan','Plan'],['methods','Métodos','Methods'],['calendar','Calendario','Calendar'],['chart','Gráfico','Chart'],['alerts','Avisos','Alerts'],['more','Más','More']];
const main=document.querySelector('main.wrap'),header=document.querySelector('header'),intro=header?.querySelector('.intro'),layout=main?.querySelector('.layout'),methods=main?.querySelector('#plan-financiero'),planTitle=document.getElementById('nav-plan'),reminders=document.getElementById('rem-open')?.closest('section'),tools=document.getElementById('nav-more'),currency=layout?.querySelector('.switch');
if(!main||!layout||!methods||!planTitle||!reminders||!tools||!currency)return;
const overview=main.querySelector(':scope > .overview'),install=document.getElementById('installApp')?.closest('section'),notice=Array.from(main.children).find(el=>el.classList.contains('notice')&&el!==install);
const footer=Array.from(main.children).find(el=>el.classList.contains('footer'));
const panels={};for(const [key] of entries){const panel=document.createElement('div');panel.className='app-view';panel.id='view-'+key;panel.hidden=key!=='home';panel.setAttribute('role','region');panel.setAttribute('aria-label',key);panels[key]=panel}
const plan=document.createElement('section');plan.className='overview';let node=planTitle;while(node){const next=node.nextSibling;plan.append(node);node=next}const divider=methods.querySelector(':scope > hr');if(divider)divider.remove();panels.plan.append(plan);panels.methods.append(methods);panels.alerts.append(reminders);
const more=document.createElement('section');more.className='overview more-settings';const moreTitle=document.createElement('h2');moreTitle.dataset.localLabel='moreTitle';more.append(moreTitle);const accountTitle=document.createElement('h3');accountTitle.id='account-title';accountTitle.dataset.localLabel='account';const accountRoot=document.createElement('div');accountRoot.id='account-root';more.append(accountTitle,accountRoot);const currencyLabel=document.createElement('h3');currencyLabel.dataset.localLabel='currency';more.append(currencyLabel,currency);const backupTitle=document.createElement('h3');backupTitle.dataset.localLabel='backups';more.append(backupTitle,document.getElementById('backup-panel'),tools);panels.more.append(more);if(install)panels.more.append(install);if(notice)panels.more.append(notice);if(footer)panels.more.append(footer);
if(overview)panels.home.append(overview);panels.home.append(layout);for(const [key] of entries)main.append(panels[key]);
const nav=document.createElement('nav');nav.className='bottom-nav';nav.setAttribute('aria-label','Navegación principal');const inner=document.createElement('div');inner.className='bottom-nav-inner';nav.append(inner);
function show(key,button){for(const [name] of entries)panels[name].hidden=name!==key;if(intro)intro.hidden=key!=='home';document.body.classList.toggle('secondary-view',key!=='home');for(const item of inner.querySelectorAll('button'))item.removeAttribute('aria-current');button.setAttribute('aria-current','page');window.scrollTo({top:0,left:0,behavior:'instant'})}
for(const [key] of entries){const button=document.createElement('button');button.type='button';button.dataset.target=key;button.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[key]}</svg><span data-localized-output="true"></span>`;button.addEventListener('click',()=>show(key,button));inner.append(button)}inner.firstChild.setAttribute('aria-current','page');document.body.append(nav);
function language(){const en=document.documentElement.lang==='en';nav.setAttribute('aria-label',en?'Main navigation':'Navegación principal');for(const [key,es,eng] of entries){const label=en?eng:es;inner.querySelector(`[data-target="${key}"] span`).textContent=label;panels[key].setAttribute('aria-label',label)}moreTitle.textContent=en?'Settings':'Configuración';currencyLabel.textContent=en?'Currency':'Moneda';backupTitle.textContent=en?'Backups and restore':'Respaldos y restauración';accountTitle.textContent=en?'Account':'Cuenta'}
window.MPDDNavigate=key=>{const b=inner.querySelector(`[data-target="${key}"]`);if(b)b.click()};for(const n of [moreTitle,accountTitle,currencyLabel,backupTitle])n.dataset.localizedOutput='true';document.addEventListener('deudas:languagechange',language);language();
})();
